import { fieldOf } from "../json/parse-json.ts";

/** The part of a `$.session.messages()` row the check reads. */
export type TranscriptRow = Readonly<{
  role: string;
  text: string;
  toolUses: readonly Readonly<{
    tool: string;
    input?: unknown;
    result?: unknown;
    isError?: true;
  }>[];
}>;

/** A notification block opens with this tag and may be cut before its close. */
const OPEN = "<task-notification>";
const CLOSE = "</task-notification>";
const TASK_ID = /<task-id>([^<]+)<\/task-id>/u;
const TERMINAL = /<status>(?:completed|failed|killed|stopped)<\/status>/u;

const usesOf = (rows: readonly TranscriptRow[]): TranscriptRow["toolUses"] =>
  rows.filter((row) => row.role === "assistant").flatMap((row) => row.toolUses);

const startedIn = (rows: readonly TranscriptRow[]): readonly string[] =>
  usesOf(rows)
    .filter((use) => use.tool === "Bash")
    .map((use) => fieldOf(use.result, "backgroundTaskId"))
    .filter((id): id is string => typeof id === "string");

// A notification ends a task only with a terminal status: one saying a
// command may be waiting for input carries the id, and the task runs on.
const notifiedIn = (rows: readonly TranscriptRow[]): readonly string[] =>
  rows
    .filter((row) => row.role === "user")
    .flatMap((row) => row.text.split(OPEN).slice(1))
    .map((part) => part.split(CLOSE, 1)[0] ?? "")
    .filter((block) => TERMINAL.test(block))
    .map((block) => TASK_ID.exec(block)?.[1])
    .filter((id) => id !== undefined);

// A successful TaskStop ends its task; the engine adds no notification then.
const stoppedIn = (rows: readonly TranscriptRow[]): readonly string[] =>
  usesOf(rows)
    .filter(
      (use) =>
        use.tool === "TaskStop" &&
        use.isError !== true &&
        use.result !== undefined,
    )
    .map(
      (use) => fieldOf(use.input, "task_id") ?? fieldOf(use.input, "shell_id"),
    )
    .filter((id): id is string => typeof id === "string");

/**
 * The background Bash tasks still running: started by a Bash call that went
 * to the background (`result.backgroundTaskId`) and not yet ended by a
 * task-notification with a terminal status or by a successful TaskStop. No
 * API lists them; the transcript does.
 * @param rows the session's messages, oldest first
 * @returns the running tasks' ids
 */
export const runningBackgroundTasks = (
  rows: readonly TranscriptRow[],
): readonly string[] => {
  const ended = new Set([...notifiedIn(rows), ...stoppedIn(rows)]);
  return startedIn(rows).filter((id) => !ended.has(id));
};

